// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    Bank b1;
    Bank b2;

    function setUp() public {
        c = new ModifierEntrancy();
        b1 = new Bank();
        b2 = new Bank();
    }

    function testFuzz_property(uint256 chooser) public {
        chooser = bound(chooser, 0, type(uint256).max);
        // the fuzzed chooser selects which admissible counterparty (a contract whose
        // supportsToken() matches) drives the airDrop; both are equally admissible
        Bank caller = (chooser % 2 == 0) ? b1 : b2;

        vm.prank(address(caller));
        try c.airDrop() {
            // general rule: a successful airdrop to an address with no balance
            // credits the exact canonical amount (20), never more
            assertTrue(c.tokenBalance(address(caller)) == 20);
        } catch {
            // if it reverts, no credit may be granted at all
            assertTrue(c.tokenBalance(address(caller)) == 0);
        }
    }
}

contract Bank {
    function supportsToken() external pure returns (bytes32) {
        return (keccak256(abi.encodePacked("Nu Token")));
    }
}
